              width: '100%', 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center',
              gap: '8px', 
              padding: '10px 12px', 
              borderRadius: '12px', 
              border: '1.5px solid rgba(234, 67, 53, 0.25)', 
